@Test
public void testGetAclTCRResponse() throws IOException {
    Mockito.doReturn(false).when(accessService).hasGlobalAdminGroup(user1);
    Assert.assertEquals(0, aclTCRService.getAclTCRResponse(projectDefault, user1, true, true).size());
    AclTCRManager manager = aclTCRService.getManager(AclTCRManager.class, projectDefault);
    manager.updateAclTCR(new AclTCR(), user1, true);
    Assert.assertTrue(aclTCRService.getAclTCRResponse(projectDefault, user1, true, true).stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> "TEST_ORDER".equals(t.getTableName()))));
    AclTCR aclTCR = new AclTCR();
    AclTCR.Table table = new AclTCR.Table();
    AclTCR.ColumnRow columnRow1 = new AclTCR.ColumnRow();
    AclTCR.Column column1 = new AclTCR.Column();
    AclTCR.Row row1 = new AclTCR.Row();
    AclTCR.RealRow realRow1 = new AclTCR.RealRow();
    realRow1.addAll(Arrays.asList("100100", "100101", "100102"));
    row1.put("ORDER_ID", realRow1);
    row1.put("BUYER_ID", null);
    columnRow1.setRow(row1);
    column1.addAll(Arrays.asList("ORDER_ID", "BUYER_ID", "TEST_DATE_ENC"));
    columnRow1.setColumn(column1);
    columnRow1.setColumnSensitiveDataMask(Lists.newArrayList(new SensitiveDataMask("ORDER_ID", SensitiveDataMask.MaskType.AS_NULL)));
    table.put("DEFAULT.TEST_ORDER", columnRow1);
    table.put("DEFAULT.TEST_ACCOUNT", null);
    AclTCR.ColumnRow columnRow2 = new AclTCR.ColumnRow();
    AclTCR.Row row2 = new AclTCR.Row();
    AclTCR.RealRow realRow2 = new AclTCR.RealRow();
    realRow2.addAll(Arrays.asList("country_a", "country_b"));
    row2.put("COUNTRY", realRow2);
    columnRow2.setRow(row2);
    table.put("DEFAULT.TEST_COUNTRY", columnRow2);
    aclTCR.setTable(table);
    manager.updateAclTCR(aclTCR, user1, true);
    List<AclTCRResponse> responses = aclTCRService.getAclTCRResponse(projectDefault, user1, true, true);
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> "TEST_ORDER".equals(t.getTableName()))));
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().noneMatch(t -> "TEST_SITES".equals(t.getTableName()))));
    responses = aclTCRService.getAclTCRResponse(projectDefault, user1, true, false);
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> t.isAuthorized() && "TEST_ORDER".equals(t.getTableName()))));
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> !t.isAuthorized() && "TEST_SITES".equals(t.getTableName()))));
    Assert.assertEquals(3, responses.stream().filter(resp -> "DEFAULT".equals(resp.getDatabaseName())).findAny().get().getAuthorizedTableNum());
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> t.getColumns().stream().anyMatch(c -> c.isAuthorized() && "ORDER_ID".equals(c.getColumnName())))));
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> t.getColumns().stream().anyMatch(c -> c.isAuthorized() && "BUYER_ID".equals(c.getColumnName())))));
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> t.getColumns().stream().anyMatch(c -> c.isAuthorized() && "COUNTRY".equals(c.getColumnName())))));
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> t.getColumns().stream().anyMatch(c -> !c.isAuthorized() && "TEST_TIME_ENC".equals(c.getColumnName())))));
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> t.getRows().stream().anyMatch(r -> "COUNTRY".equals(r.getColumnName()) && "country_a,country_b".equals(String.join(",", r.getItems()))))));
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> t.getColumns().stream().anyMatch(c -> "ORDER_ID".equals(c.getColumnName()) && c.getDataMaskType() == SensitiveDataMask.MaskType.AS_NULL))));
    Assert.assertTrue(responses.stream().anyMatch(resp -> resp.getTables().stream().anyMatch(t -> t.getColumns().stream().anyMatch(c -> "BUYER_ID".equals(c.getColumnName()) && "bigint".equals(c.getDatatype())))));
}

@Test
public void testMergeACLTCRWithRevokeGrantColumns() throws IOException {
    // grant acl tcr
    Mockito.doReturn(false).when(accessService).hasGlobalAdminGroup(user1);
    Assert.assertEquals(0, aclTCRService.getAclTCRResponse(projectDefault, user1, true, true).size());
    AclTCRManager manager = aclTCRService.getManager(AclTCRManager.class, projectDefault);
    manager.updateAclTCR(new AclTCR(), user1, true);
    List<AclTCRResponse> response = aclTCRService.getAclTCRResponse(projectDefault, user1, true, false);
    AtomicInteger totalTableNum = new AtomicInteger();
    AtomicInteger authorizedTableNum = new AtomicInteger();
    AtomicInteger totalColumnNum = new AtomicInteger();
    AtomicInteger authorizedColumnNum = new AtomicInteger();
    Assert.assertTrue(response.stream().filter(aclTCRResponse -> aclTCRResponse.getDatabaseName().equals("EDW")).anyMatch(aclTCRResponse -> aclTCRResponse.getTables().stream().filter(table -> table.getTableName().equals("TEST_SELLER_TYPE_DIM")).anyMatch(table -> {
        totalTableNum.set(aclTCRResponse.getTotalTableNum());
        authorizedTableNum.set(aclTCRResponse.getAuthorizedTableNum());
        totalColumnNum.set(table.getTotalColumnNum());
        authorizedColumnNum.set(table.getAuthorizedColumnNum());
        return table.getColumns().stream().anyMatch(column -> column.isAuthorized() && column.getColumnName().equals("DIM_CRE_USER"));
    })));
    Assert.assertTrue(totalTableNum.get() > 0);
    Assert.assertTrue(authorizedTableNum.get() > 0);
    Assert.assertTrue(totalColumnNum.get() > 0);
    Assert.assertTrue(authorizedColumnNum.get() > 0);
    // revoke column
    AclTCRRequest request = new AclTCRRequest();
    request.setDatabaseName("EDW");
    AclTCRRequest.Table tableRequest = new AclTCRRequest.Table();
    tableRequest.setTableName("TEST_SELLER_TYPE_DIM");
    tableRequest.setAuthorized(true);
    AclTCRRequest.Column columnRequest = new AclTCRRequest.Column();
    columnRequest.setColumnName("DIM_CRE_USER");
    columnRequest.setAuthorized(false);
    tableRequest.setColumns(Collections.singletonList(columnRequest));
    request.setTables(Collections.singletonList(tableRequest));
    aclTCRService.mergeAclTCR(projectDefault, user1, true, Collections.singletonList(request));
    response = aclTCRService.getAclTCRResponse(projectDefault, user1, true, false);
    Assert.assertTrue(response.stream().filter(aclTCRResponse -> aclTCRResponse.getDatabaseName().equals("EDW")).anyMatch(aclTCRResponse -> aclTCRResponse.getTables().stream().filter(table -> table.getTableName().equals("TEST_SELLER_TYPE_DIM")).anyMatch(table -> table.getAuthorizedColumnNum() == authorizedColumnNum.get() - 1 && table.getColumns().stream().anyMatch(column -> !column.isAuthorized() && column.getColumnName().equals("DIM_CRE_USER")))));
    // grant columnRequest
    columnRequest.setColumnName("DIM_CRE_USER");
    columnRequest.setAuthorized(true);
    tableRequest.setColumns(Collections.singletonList(columnRequest));
    request.setTables(Collections.singletonList(tableRequest));
    aclTCRService.mergeAclTCR(projectDefault, user1, true, Collections.singletonList(request));
    response = aclTCRService.getAclTCRResponse(projectDefault, user1, true, false);
    Assert.assertTrue(response.stream().filter(aclTCRResponse -> aclTCRResponse.getDatabaseName().equals("EDW")).anyMatch(aclTCRResponse -> aclTCRResponse.getTables().stream().filter(table -> table.getTableName().equals("TEST_SELLER_TYPE_DIM")).anyMatch(table -> table.getAuthorizedColumnNum() == authorizedColumnNum.get() && table.getColumns().stream().anyMatch(column -> column.isAuthorized() && column.getColumnName().equals("DIM_CRE_USER")))));
}

