@Test
public void testUpdateMetadata() {
    qhMetaUpdateScheduler.queryHistoryDAO = Mockito.mock(RDBMSQueryHistoryDAO.class);
    qhMetaUpdateScheduler.accelerateRuleUtil = Mockito.mock(AccelerateRuleUtil.class);
    Mockito.when(qhMetaUpdateScheduler.queryHistoryDAO.queryQueryHistoriesByIdOffset(Mockito.anyLong(), Mockito.anyInt(), Mockito.eq(USAGE_METER_PROJECT))).thenReturn(queryHistories()).thenReturn(null);
    // before update dataflow usage, layout usage and last query time
    NDataflow dataflow = NDataflowManager.getInstance(KylinConfig.getInstanceFromEnv(), USAGE_METER_PROJECT).getDataflow(USAGE_METER_PROJECT_DATAFLOW);
    Assert.assertEquals(3, dataflow.getQueryHitCount());
    Assert.assertNull(dataflow.getLayoutHitCount().get(20000000001L));
    Assert.assertNull(dataflow.getLayoutHitCount().get(1000001L));
    Assert.assertEquals(0L, dataflow.getLastQueryTime());
    // before update id offset
    QueryHistoryIdOffsetManager idOffsetManager = QueryHistoryIdOffsetManager.getInstance(USAGE_METER_PROJECT);
    Assert.assertEquals(0, idOffsetManager.get(META).getOffset());
    // run update
    //
    QueryHistoryMetaUpdateScheduler.QueryHistoryMetaUpdateRunner //
    queryHistoryAccelerateRunner = qhMetaUpdateScheduler.new QueryHistoryMetaUpdateRunner(USAGE_METER_PROJECT);
    queryHistoryAccelerateRunner.run();
    // after update dataflow usage, layout usage and last query time
    dataflow = NDataflowManager.getInstance(KylinConfig.getInstanceFromEnv(), USAGE_METER_PROJECT).getDataflow(USAGE_METER_PROJECT_DATAFLOW);
    Assert.assertEquals(6, dataflow.getQueryHitCount());
    Assert.assertEquals(2, dataflow.getLayoutHitCount().get(20000000001L).getDateFrequency().get(TimeUtil.getDayStart(QUERY_TIME)).intValue());
    Assert.assertEquals(1, dataflow.getLayoutHitCount().get(1000001L).getDateFrequency().get(TimeUtil.getDayStart(QUERY_TIME)).intValue());
    Assert.assertEquals(1586760398338L, dataflow.getLastQueryTime());
    // update snapshot usage
    NTableMetadataManager tableMetadataManager = NTableMetadataManager.getInstance(KylinConfig.getInstanceFromEnv(), USAGE_METER_PROJECT);
    Assert.assertEquals(1, tableMetadataManager.getOrCreateTableExt("SSB.LINEORDER").getSnapshotHitCount());
    Assert.assertEquals(2, tableMetadataManager.getOrCreateTableExt("SSB.CUSTOMER").getSnapshotHitCount());
    // update internal table usage
    InternalTableManager internalTableManager = InternalTableManager.getInstance(KylinConfig.getInstanceFromEnv(), USAGE_METER_PROJECT);
    Assert.assertEquals(1, internalTableManager.getInternalTableDesc("SSB.CUSTOMER").getHitCount());
    // after update id offset
    Assert.assertEquals(8, idOffsetManager.get(META).getOffset());
}

