    for (int i = 0; i < 400; i++) {
        LayoutEntity layout = new LayoutEntity();
        layout.setId(INDEX_ID_STEP + i + 1);
        layout.setBase(false);
        layout.setToBeDeleted(true);
        // generating different hashcode for comparison
        layout.setStorageType(i + 800);
