    NTableMetadataManager tManager = NTableMetadataManager.getInstance(config, PROJECT);
    ExecutableManager executableManager = ExecutableManager.getInstance(config, PROJECT);
    TableDesc table = tManager.getTableDesc(TABLE_INDENTITY);
    internalTableService.createInternalTable(PROJECT, TABLE_INDENTITY, new String[] { PARTITION_COL }, null, new HashMap<>(), InternalTableDesc.StorageType.PARQUET.name());
    // refresh non-time col partitions
    internalTableService.loadIntoInternalTable(PROJECT, table.getName(), table.getDatabase(), false, true, "", "", new String[] { "FP-GTC", "ABIN" }, null);
    // check incremental refresh an un-time-partitioned table
    Assertions.assertThrows(Exception.class, () -> internalTableService.loadIntoInternalTable(PROJECT, table.getName(), table.getDatabase(), true, true, "1293811200000", "1420041600000", null, null));
