    String finalJobId2 = jobId;
    await().atMost(2, TimeUnit.MINUTES).until(() -> {
        ExecutableState state = executableManager.getJob(finalJobId2).getStatus();
        return state.isFinalState() || state == ExecutableState.ERROR;
    });
    // submit 2 incremental jobs without time overlap
    response = internalTableService.loadIntoInternalTable(PROJECT, table.getName(), table.getDatabase(), true, false, "694195200000", "694368000000", null, // 1992-01-01 ～ 1992-01-03
    null);
    internalTableService.loadIntoInternalTable(PROJECT, table.getName(), table.getDatabase(), true, false, "694454400000", "694713600000", null, // 1992-01-04 ～ 1992-01-07
    null);
    jobId = response.getJobs().get(0).getJobId();
    String finalJobId3 = jobId;
    await().atMost(2, TimeUnit.MINUTES).until(() -> {
        ExecutableState state = executableManager.getJob(finalJobId3).getStatus();
        return state.isFinalState() || state == ExecutableState.ERROR;
    });
    // test cancel a full load job
    internalTableService.truncateInternalTable(PROJECT, TABLE_INDENTITY);
    jobId = internalTableService.loadIntoInternalTable(PROJECT, table.getName(), table.getDatabase(), false, false, "", "", null, null).getJobs().get(0).getJobId();
    executableManager.discardJob(jobId);
}

