    modelService.deleteSegmentById("741ca86a-1f13-46da-a59f-95fb68615e3a", "default", new String[] { segments.get(2).getId(), segments.get(3).getId() }, false);
    Assert.assertEquals(4, df2.getSegments().size());
}

