    SecurityContextHolder.getContext().setAuthentication(new TestingAuthenticationToken("ADMIN", "ADMIN", Constant.ROLE_ADMIN));
    createTestMetadata();
    NProjectManager projectManager = NProjectManager.getInstance(KylinConfig.getInstanceFromEnv());
    ProjectInstance projectInstance = projectManager.getProject("default");
    LinkedHashMap<String, String> overrideKylinProps = projectInstance.getOverrideKylinProps();
    overrideKylinProps.put("kylin.query.force-limit", "-1");
    overrideKylinProps.put("kylin.source.default", "11");
    ProjectInstance projectInstanceUpdate = ProjectInstance.create(projectInstance.getName(), projectInstance.getOwner(), projectInstance.getDescription(), overrideKylinProps);
    projectManager.updateProject(projectInstance, projectInstanceUpdate.getName(), projectInstanceUpdate.getDescription(), projectInstanceUpdate.getOverrideKylinProps());
    ReflectionTestUtils.setField(aclEvaluate, "aclUtil", Mockito.spy(AclUtil.class));
    ReflectionTestUtils.setField(tableSampleService, "aclEvaluate", aclEvaluate);
    // init factory
    new NTableSamplingJob();
    JobContextUtil.cleanUp();
    JobContextUtil.getJobInfoDao(getTestConfig());
    JobContext jobContext = JobContextUtil.getJobContext(getTestConfig());
    // need not start job scheduler
    jobContext.destroy();
}

@Test
public void testProxy() throws Exception {
    createTestMetadata();
    MockedStatic<SparkUIUtil> mockedSparkUIUtil = Mockito.mockStatic(SparkUIUtil.class);
    jobDriverUIUtil = Mockito.spy(new JobDriverUIUtil());
    Field field = jobDriverUIUtil.getClass().getDeclaredField("jobInfoService");
    field.setAccessible(true);
    field.set(jobDriverUIUtil, jobInfoService);
    Mockito.when(jobInfoService.getOriginTrackUrlByProjectAndStepId(any(), any())).thenReturn("http://testServer:4040");
    request.setRequestURI("/kylin/driver_ui/project/step/job");
    request.setMethod("GET");
    jobDriverUIUtil.proxy("project", "step", request, response);
    Mockito.when(jobInfoService.getOriginTrackUrlByProjectAndStepId(any(), any())).thenReturn(null);
    jobDriverUIUtil.proxy("project", "step", request, response);
    assert response.getContentAsString().contains("track url not generated yet");
    response = new MockHttpServletResponse();
    Mockito.when(jobInfoService.getOriginTrackUrlByProjectAndStepId(any(), any())).thenReturn("http://testServer:4040");
    mockedSparkUIUtil.when(() -> SparkUIUtil.resendSparkUIRequest(any(), any(), eq("http://testServer:4040"), eq("/job"), eq("/kylin/driver_ui/project/step"))).thenThrow(UnknownHostException.class);
    jobDriverUIUtil.proxy("project", "step", request, response);
    assert response.getContentAsString().contains("track url invalid already");
    assert JobDriverUIUtil.getProxyUrl("project", "step").equals("/kylin/driver_ui/project/step");
    mockedSparkUIUtil.close();
}

