    request.setSimplifiedDimensions(model.getAllNamedColumns().stream().filter(NDataModel.NamedColumn::isDimension).filter(f -> f.getAliasDotColumn().contains("TEST_KYLIN_FACT")).collect(Collectors.toList()).subList(0, 2));
    request.setSimplifiedMeasures(model.getAllMeasures().stream().filter(m -> !m.isTomb()).filter(m -> m.getId() == 100000).map(SimplifiedMeasure::fromMeasure).collect(Collectors.toList()).subList(0, 1));
    request.setWithBaseIndex(true);
    val requestj = JsonUtil.readValue(JsonUtil.writeValueAsString(request), ModelRequest.class);
    modelService.updateDataModelSemantic(getProject(), requestj);
    // add 1 agg groups
    NAggregationGroup newAggregationGroup = new NAggregationGroup();
    newAggregationGroup.setIncludes(new Integer[] { 1, 2 });
    newAggregationGroup.setMeasures(new Integer[] { 100000 });
    val selectRule = new SelectRule();
    selectRule.mandatoryDims = new Integer[0];
    selectRule.hierarchyDims = new Integer[0][0];
    selectRule.jointDims = new Integer[0][0];
    newAggregationGroup.setSelectRule(selectRule);
    UnitOfWork.doInTransactionWithRetry(() -> {
        indexPlanService.updateRuleBasedCuboid(getProject(), UpdateRuleBasedCuboidRequest.builder().project(getProject()).modelId(BASIC_MODEL).aggregationGroups(Lists.newArrayList(newAggregationGroup)).build());
