    request3.setProject(project);
    request3.setUuid(BASIC_MODEL);
    request3.setSimplifiedDimensions(model.getAllNamedColumns().stream().filter(NDataModel.NamedColumn::isDimension).filter(f -> f.getAliasDotColumn().contains("TEST_KYLIN_FACT")).collect(Collectors.toList()).subList(0, 3));
    request3.setSimplifiedMeasures(model.getAllMeasures().stream().filter(m -> !m.isTomb()).filter(m -> m.getId() == 100000).map(SimplifiedMeasure::fromMeasure).collect(Collectors.toList()).subList(0, 1));
    request3.setWithBaseIndex(true);
    val requestj3 = JsonUtil.readValue(JsonUtil.writeValueAsString(request3), ModelRequest.class);
