    val indexPlanManager = NIndexPlanManager.getInstance(KylinConfig.getInstanceFromEnv(), getProject());
    // create measure
    var request = newSemanticRequest(BASIC_MODEL);
    val newMeasure1 = new SimplifiedMeasure();
