@Test
public void testQueryReachLimit() throws Exception {
    Mockito.doReturn(SUCCESS).when(asyncQueryService).queryStatus(Mockito.anyString(), Mockito.anyString());
    SQLResponse response = new SQLResponse();
    response.setException(false);
    Mockito.doReturn(response).when(kapQueryService).queryWithCache(Mockito.any());
    getTestConfig().setProperty("kylin.query.unique-async-query-yarn-queue-enabled", "true");
    getTestConfig().setProperty("kylin.query.async-query.max-concurrent-jobs", "3");
    reloadAsyncQueryRequestLimits();
    AsyncQueryRequestLimits limit1 = new AsyncQueryRequestLimits();
    AsyncQueryRequestLimits limit2 = new AsyncQueryRequestLimits();
    mockMvc.perform(MockMvcRequestBuilders.post("/api/async_query").contentType(MediaType.APPLICATION_JSON).content(JsonUtil.writeValueAsString(mockAsyncQuerySQLRequest())).accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_JSON))).andExpect(MockMvcResultMatchers.status().isOk());
    Mockito.verify(nAsyncQueryController).query(Mockito.any());
    AsyncQueryRequestLimits limits3 = new AsyncQueryRequestLimits();
    mockMvc.perform(MockMvcRequestBuilders.post("/api/async_query").contentType(MediaType.APPLICATION_JSON).content(JsonUtil.writeValueAsString(mockAsyncQuerySQLRequest())).accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_JSON))).andExpect(MockMvcResultMatchers.status().is5xxServerError()).andExpect(result -> {
        Assert.assertTrue(result.getResolvedException() instanceof KylinException);
        Assert.assertEquals(TOO_MANY_ASYNC_QUERY.toErrorCode().getCodeString(), ((KylinException) result.getResolvedException()).getErrorCode().getCodeString());
        Assert.assertEquals(MsgPicker.getMsg().getAsyncQueryTooManyRunning(), result.getResolvedException().getMessage());
    });
    limits3.close();
    mockMvc.perform(MockMvcRequestBuilders.post("/api/async_query").contentType(MediaType.APPLICATION_JSON).content(JsonUtil.writeValueAsString(mockAsyncQuerySQLRequest())).accept(MediaType.parseMediaType(HTTP_VND_APACHE_KYLIN_JSON))).andExpect(MockMvcResultMatchers.status().isOk());
    limit1.close();
    limit2.close();
}

