    Assert.assertEquals(3, metricsResponse.size());
    Assert.assertEquals(500, (double) metricsResponse.get("nmodel_basic"), 0.1);
    Assert.assertEquals(600, (double) metricsResponse.get("all_fixed_length"), 0.1);
