    Mockito.when(segments.getSegments(READY, WARNING)).thenReturn(segments);
    glutenCacheService.indexGlutenCache(request, servletRequest);
    ArgumentCaptor<LogEvent> logCaptor = ArgumentCaptor.forClass(LogEvent.class);
    Mockito.verify(appender, Mockito.atLeast(0)).append(logCaptor.capture());
    var log = logCaptor.getAllValues().stream().filter(event -> event.getLoggerName().equals(GlutenCacheService.class.getName())).filter(event -> event.getLevel().equals(Level.INFO)).map(event -> event.getMessage().getFormattedMessage()).findFirst().orElseThrow(AssertionError::new);
    Assert.assertEquals(String.format(Locale.ROOT, "Model[%s] cache command is [%s]", MODEL, GENERATE_MODEL_CACHE_COMMANDS_BY_SEGMENTS), log);
