@Test
public void testLoadSqls() throws IOException {
    // import multiple files
    MockMultipartFile file1 = new MockMultipartFile("sqls1.sql", "sqls1.sql", "text/plain", Files.newInputStream(new File("./src/test/resources/ut_sqls_file/sqls1.sql").toPath()));
    MockMultipartFile file2 = new MockMultipartFile("sqls2.txt", "sqls2.txt", "text/plain", Files.newInputStream(new File("./src/test/resources/ut_sqls_file/sqls2.txt").toPath()));
    // add jdbc type sql
    MockMultipartFile file3 = new MockMultipartFile("sqls3.txt", "sqls3.txt", "text/plain", Files.newInputStream(new File("./src/test/resources/ut_sqls_file/sqls3.txt").toPath()));
    MockMultipartFile exceptionFile = new MockMultipartFile("exception_file.sql", "exception_file.sql", "text/plain", "".getBytes(StandardCharsets.UTF_8));
    MockMultipartFile errorFile = new MockMultipartFile("error_file.sql", "error_file.sql", "text/plain", "".getBytes(StandardCharsets.UTF_8));
    Mockito.when(favoriteRuleService.transformFileToSqls(exceptionFile, PROJECT)).thenThrow(IOException.class);
    Mockito.when(favoriteRuleService.transformFileToSqls(errorFile, PROJECT)).thenThrow(Error.class);
    SQLParserResponse result = favoriteRuleService.importSqls(new MultipartFile[] { file1, file2, file3, exceptionFile, errorFile }, PROJECT);
    List<ImportSqlResponse> responses = result.getData();
    Assert.assertEquals(10, responses.size());
    Assert.assertFalse(responses.get(0).isCapable());
    Assert.assertTrue(responses.get(8).isCapable());
    Assert.assertEquals(10, result.getSize());
    Assert.assertEquals(3, result.getCapableSqlNum());
    List<String> failedFilesMsg = result.getWrongFormatFile();
    Assert.assertEquals(2, failedFilesMsg.size());
    Assert.assertEquals("exception_file.sql", failedFilesMsg.get(0));
    Assert.assertEquals("error_file.sql", failedFilesMsg.get(1));
    // import empty file
    MockMultipartFile emptyFile = new MockMultipartFile("empty_file.sql", "empty_file.sql", "text/plain", "".getBytes(StandardCharsets.UTF_8));
    result = favoriteRuleService.importSqls(new MultipartFile[] { emptyFile }, PROJECT);
    Assert.assertNotNull(result);
    Assert.assertEquals(0, result.getSize());
}

