@Test
public void testRenew() {
    NodeRegistryManager manager = NodeRegistryManager.getInstance(getTestConfig());
    manager.createNodeRegistryIfNotExists();
    List<NodeRegistry.NodeInstance> nodeInstances = manager.getNodeRegistry().getNodeInstances(ServerModeEnum.ALL);
    assertEquals(1, nodeInstances.size());
    NodeRegistry.NodeInstance instance = nodeInstances.get(0);
    nodeRegistryService.scheduleRenew();
    List<NodeRegistry.NodeInstance> newNodeInstances = manager.getNodeRegistry().getNodeInstances(ServerModeEnum.ALL);
    assertEquals(1, newNodeInstances.size());
    NodeRegistry.NodeInstance newInstance = newNodeInstances.get(0);
    assertTrue(newInstance.getLastHeartbeatTS() > instance.getLastHeartbeatTS());
}

@Test
@SuppressWarnings("unchecked")
public void testCheckAndClean() {
    NodeRegistryManager manager = NodeRegistryManager.getInstance(getTestConfig());
    manager.createNodeRegistryIfNotExists();
    CachedCrudAssist<NodeRegistry> crud = (CachedCrudAssist<NodeRegistry>) ReflectionTestUtils.getField(manager, "crud");
    assertNotNull(crud);
    NodeRegistry nodeRegistry = crud.copyForWrite(manager.getNodeRegistry());
    NodeRegistry.NodeInstance timeoutInstance = new NodeRegistry.NodeInstance("123.123.123.123", 7070, ServerModeEnum.QUERY);
    ReflectionTestUtils.setField(timeoutInstance, "lastHeartbeatTS", System.currentTimeMillis() - getTestConfig().getNodeRegistryJdbcExpireThreshold() - 500);
    nodeRegistry.registerOrUpdate(timeoutInstance);
    crud.save(nodeRegistry);
    List<NodeRegistry.NodeInstance> nodeInstances = manager.getNodeRegistry().getNodeInstances(ServerModeEnum.QUERY);
    assertEquals(1, nodeInstances.size());
    overwriteSystemProp("kylin.metadata.distributed-lock-impl", "org.apache.kylin.common.lock.LocalLockFactory");
    nodeRegistryService.scheduleCheck();
    List<NodeRegistry.NodeInstance> newNodeInstances = manager.getNodeRegistry().getNodeInstances(ServerModeEnum.QUERY);
    assertTrue(newNodeInstances.isEmpty());
}

@Test
public void testPreDestroy() {
    EnhancedUnitOfWork.doInTransactionWithCheckAndRetry(UnitOfWorkParams.builder().unitName(UnitOfWork.GLOBAL_UNIT).projectId(StringUtils.EMPTY).readonly(false).maxRetry(1).processor(() -> {
