@Test
public void testGetLoc() throws Exception {
    NSparkMetadataExplorer sparkMetadataExplorer = new NSparkMetadataExplorer();
    NTableMetadataManager tableMgr = NTableMetadataManager.getInstance(getTestConfig(), "default");
    TableDesc fact = tableMgr.getTableDesc("DEFAULT.TEST_KYLIN_FACT");
    sparkMetadataExplorer.createSampleTable(fact);
    SparkSession sparkSession = Mockito.mock(SparkSession.class, Mockito.RETURNS_DEEP_STUBS);
    Mockito.when(sparkSession.sql("desc formatted " + "TEST_KYLIN_FACT").where("col_name == 'Location'").head().getString(1)).thenReturn("hdfs://hacluster//src/spark-project/examples/test_data/27578/spark-warehouse/test_kylin_fact");
    Assert.assertTrue(sparkMetadataExplorer.getLoc(sparkSession, "TEST_KYLIN_FACT", null).contains("hdfs://hacluster"));
    Assert.assertTrue(sparkMetadataExplorer.getLoc(sparkSession, "TEST_KYLIN_FACT", "hdfs://writecluster").contains("hdfs://writecluster"));
    Mockito.when(sparkSession.sql("desc formatted " + "TEST_KYLIN_FACT").where("col_name == 'Location'").head().getString(1)).thenReturn(null);
    Assert.assertNull(sparkMetadataExplorer.getLoc(sparkSession, "TEST_KYLIN_FACT", "hdfs://writecluster"));
}

