    Assert.assertEquals("default", helper.getConf(SparkConfHelper.DEFAULT_QUEUE));
    helper.applySparkConf(sparkConf);
    Assert.assertEquals("default", sparkConf.get(SparkConfHelper.DEFAULT_QUEUE));
}

